begin;

alter table if exists public.news
  add column if not exists source_url text,
  add column if not exists title_en text,
  add column if not exists summary text,
  add column if not exists summary_en text,
  add column if not exists content_en text,
  add column if not exists image_url text,
  add column if not exists category_id bigint,
  add column if not exists location_id bigint,
  add column if not exists is_hidden boolean not null default false,
  add column if not exists is_featured boolean not null default false,
  add column if not exists sent_notification boolean not null default true,
  add column if not exists view_count integer not null default 0;

insert into public.news (
  title, title_en, summary, summary_en, content, content_en,
  image_url, source_url, category_id, location_id, created_at,
  is_hidden, is_featured, sent_notification, view_count
)
select
  'البورد العربي يعقد اجتماعه الأول لعام 2026 بمشاركة وزراء صحة عرب',
  'The Arab Board holds its first meeting in 2026 with the participation of Arab health ministers',
  'عقدت الهيئة العامة للمجلس العربي للاختصاصات الصحية، اليوم السبت 4 نيسان، اجتماعاً هو الأول لها لعام 2026، وقد عُقد الاجتماع عن بعد بمشاركة عدد من وزراء الصحة العرب، لبحث سبل تطوير التدريب الطبي وتعزيز التعاون بما ينعكس إيجاباً على جودة الخدمات الصحية في الدول العربية وأكد وزير الصحة ونائب رئيس الهيئة العليا للمجلس مصعب العلي، […]',
  'Today, Saturday, April 4, the General Authority of the Arab Board for Health Specialties held its first meeting for the year 2026. The meeting was held remotely with the participation of a number of Arab health ministers, to discuss ways to develop medical training and enhance cooperation in a way that reflects positively on the quality of health services in the Arab countries. The Minister of Health and Vice President of the Council’s Supreme Authority, Musab Al-Ali, confirmed […]',
  'عقدت الهيئة العامة للمجلس العربي للاختصاصات الصحية، اليوم السبت 4 نيسان، اجتماعاً هو الأول لها لعام 2026، وقد عُقد الاجتماع عن بعد بمشاركة عدد من وزراء الصحة العرب، لبحث سبل تطوير التدريب الطبي وتعزيز التعاون بما ينعكس إيجاباً على جودة الخدمات الصحية في الدول العربية وأكد وزير الصحة ونائب رئيس الهيئة العليا للمجلس مصعب العلي، خلال الاجتماع، أن عدد الأطباء المتدربين في المراكز المعتمدة في سوريا تجاوز 2000 متدرب، مشيراً إلى دورهم المحوري في دعم وتطوير القطاع الصحي، في ظل استمرار التنسيق مع المجلس العربي والجهات الأكاديمية الوطنية. وشدد العلي على أهمية تبادل الخبرات وتعزيز التكامل العربي في مجالات التدريب والاعتماد الطبي، بما يسهم في بناء كفاءات طبية قادرة على تلبية احتياجات الأنظمة الصحية العربية، بحسب ما نشرت وزارة الصحة عبر معرفاتها الرسمية. ودعا الوزير في ختام كلمته وزراء الصحة العرب لحضور اجتماع الهيئة العليا للمجلس المقرر عقده في دمشق خلال شهر تشرين الأول، مؤكداً أن هذه الخطوة تعكس عودة سوريا إلى المساهمة الفاعلة في منظومة التدريب الطبي العربي. وفي 2 نيسان الحالي، انطلق المؤتمر العلمي الأول لنقابة أطباء سوريا الذي عُقد في فندق البوابات السبع بدمشق تحت عنوان “المستجدات في الاختصاصات الطبية البشرية”، بحضور وزير الصحة مصعب العلي، ووزير التعليم العالي والبحث العلمي مروان الحلبي.',
  'Today, Saturday, April 4, the General Authority of the Arab Board for Health Specializations held its first meeting for the year 2026. The meeting was held remotely with the participation of a number of Arab health ministers, to discuss ways to develop medical training and enhance cooperation in a way that reflects positively on the quality of health services in Arab countries. The Minister of Health and Vice President of the Supreme Council Musab Al-Ali confirmed, during the meeting, that the number of doctors trained in accredited centers in Syria exceeded 2,000 trainees, pointing to their pivotal role in supporting and developing the sector. Health, in light of continued coordination with the Arab Council and national academic bodies. Al-Ali stressed the importance of exchanging experiences and enhancing Arab integration in the fields of medical training and accreditation, which contributes to building medical competencies capable of meeting the needs of Arab health systems, according to what the Ministry of Health published through its official accounts. At the end of his speech, the Minister called on the Arab health ministers to attend the meeting of the Council’s Supreme Authority scheduled to be held in Damascus during the month of October, stressing that this step reflects Syria’s return to effective contribution to the Arab medical training system. On April 2, the first scientific conference of the Syrian Doctors Syndicate was launched, which was held at the Seven Gates Hotel in Damascus under the title “Developments in Human Medical Specialties,” in the presence of the Minister of Health, Musab Al-Ali, and the Minister of Higher Education and Scientific Research, Marwan Al-Halabi.',
  'https://alikhbariah.com/wp-content/uploads/2026/04/Arab-Board.jpg',
  'https://alikhbariah.com/%d8%a7%d9%84%d8%a8%d9%88%d8%b1%d8%af-%d8%a7%d9%84%d8%b9%d8%b1%d8%a8%d9%8a-%d9%8a%d8%b9%d9%82%d8%af-%d8%a7%d8%ac%d8%aa%d9%85%d8%a7%d8%b9%d9%87-%d8%a7%d9%84%d8%a3%d9%88%d9%84-%d9%84%d8%b9%d8%a7%d9%85-20/',
  (select id from public.categories where slug = 'news-health' and type = 'news' limit 1),
  (select id from public.locations where slug = 'syria' limit 1),
  '2026-04-04T09:00:55Z'::timestamptz,
  false, true, true, 0
where not exists (
  select 1 from public.news n where n.title = 'البورد العربي يعقد اجتماعه الأول لعام 2026 بمشاركة وزراء صحة عرب'
     or coalesce(to_jsonb(n)->>'source_url','') = 'https://alikhbariah.com/%d8%a7%d9%84%d8%a8%d9%88%d8%b1%d8%af-%d8%a7%d9%84%d8%b9%d8%b1%d8%a8%d9%8a-%d9%8a%d8%b9%d9%82%d8%af-%d8%a7%d8%ac%d8%aa%d9%85%d8%a7%d8%b9%d9%87-%d8%a7%d9%84%d8%a3%d9%88%d9%84-%d9%84%d8%b9%d8%a7%d9%85-20/'
);

