  title, title_en, summary, summary_en, content, content_en,
  image_url, source_url, category_id, location_id, created_at,
  is_hidden, is_featured, sent_notification, view_count
)
select
  'مديرية إعلام ريف دمشق تنفي توغل الاحتلال الإسرائيلي في بيت جن',
  'The Damascus Countryside Media Directorate denies the Israeli occupation’s incursion into Beit Jinn',
  'نفت مديرية إعلام ريف دمشق، السبت 4 نيسان، الأخبار المتداولة حول توغل جيش الاحتلال الإسرائيلي في بلدة بيت جن بريف دمشق، وإطلاقهم النار على المدنيين هناك. جاء ذلك بعد تداول شائعات وأخبار غير دقيقة تناقلتها وسائل الإعلام ومنصات التواصل الاجتماعي، ما دفع الجهات الرسمية إلى إصدار توضيحات لنفي هذه الشائعات، والتأكيد على ضرورة الاعتماد على […]',
  'On Saturday, April 4, the Rural Damascus Media Directorate denied the news circulating about the Israeli occupation army’s incursion into the town of Beit Jinn in the Damascus countryside, and their shooting at civilians there. This came after the circulation of rumors and inaccurate news carried by the media and social media platforms, which prompted the official authorities to issue clarifications to deny these rumours, and to emphasize the necessity of relying on [...]',
  'نفت مديرية إعلام ريف دمشق، السبت 4 نيسان، الأخبار المتداولة حول توغل جيش الاحتلال الإسرائيلي في بلدة بيت جن بريف دمشق، وإطلاقهم النار على المدنيين هناك. جاء ذلك بعد تداول شائعات وأخبار غير دقيقة تناقلتها وسائل الإعلام ومنصات التواصل الاجتماعي، ما دفع الجهات الرسمية إلى إصدار توضيحات لنفي هذه الشائعات، والتأكيد على ضرورة الاعتماد على المصادر الرسمية. وسبق أن نفى مصدر أمني ، الجمعة 3 نيسان، في تصريح للإخبارية ما تم تداوله حول إطلاق صواريخ من الأراضي السورية باتجاه الجولان المحتل. من جانبها، نفت مديرية إعلام القنيطرة بشكل قاطع ما يتم تداوله عبر بعض وسائل الإعلام ومنصات التواصل الاجتماعي حول هذا الشأن، مؤكدة أن هذه المزاعم لا أساس لها من الصحة. وأوضحت المديرية في بيان نشرته على معرفاتها الرسمية أن هذه الأخبار لم تصدر عن أي جهة رسمية أو مصدر موثوق، وتندرج ضمن إطار المعلومات المضللة التي تفتقر إلى الدقة.',
  'On Saturday, April 4, the Rural Damascus Media Directorate denied the news circulating about the Israeli occupation army’s incursion into the town of Beit Jinn in the Damascus countryside, and their shooting at civilians there. This came after the circulation of rumors and inaccurate news carried by the media and social media platforms, which prompted the official authorities to issue clarifications to deny these rumours, and to emphasize the necessity of relying on official sources. A security source previously denied, on Friday, April 3, in a statement to Al-Ikhbariya, what was circulated about the launching of missiles from Syrian territory towards the occupied Golan. For its part, the Quneitra Media Directorate categorically denied what is being circulated in some media outlets and social media platforms about this matter, stressing that these allegations are baseless. The Directorate explained in a statement published on its official accounts that this news was not issued by any official body or reliable source, and falls within the framework of misleading information that lacks accuracy.',
  'https://alikhbariah.com/wp-content/uploads/2026/04/Damascus-Countryside-Media-Directorate.jpg',
  'https://alikhbariah.com/%d9%85%d8%af%d9%8a%d8%b1%d9%8a%d8%a9-%d8%a5%d8%b9%d9%84%d8%a7%d9%85-%d8%b1%d9%8a%d9%81-%d8%af%d9%85%d8%b4%d9%82-%d8%aa%d9%86%d9%81%d9%8a-%d8%aa%d9%88%d8%ba%d9%84-%d8%a7%d9%84%d8%a7%d8%ad%d8%aa%d9%84/',
  (select id from public.categories where slug = 'news-local' and type = 'news' limit 1),
  (select id from public.locations where slug = 'syria' limit 1),
  '2026-04-04T08:00:37Z'::timestamptz,
  false, true, true, 0
where not exists (
  select 1 from public.news n where n.title = 'مديرية إعلام ريف دمشق تنفي توغل الاحتلال الإسرائيلي في بيت جن'
     or coalesce(to_jsonb(n)->>'source_url','') = 'https://alikhbariah.com/%d9%85%d8%af%d9%8a%d8%b1%d9%8a%d8%a9-%d8%a5%d8%b9%d9%84%d8%a7%d9%85-%d8%b1%d9%8a%d9%81-%d8%af%d9%85%d8%b4%d9%82-%d8%aa%d9%86%d9%81%d9%8a-%d8%aa%d9%88%d8%ba%d9%84-%d8%a7%d9%84%d8%a7%d8%ad%d8%aa%d9%84/'
);

