select
  'الخارجية تؤكد رفضها أي اعتداء على السفارات المعتمدة والمساس برموز الدول',
  'The Foreign Ministry confirms its rejection of any attack on accredited embassies and attacks on the symbols of countries',
  'أكدت وزارة الخارجية والمغتربين موقفها الثابت والراسخ في رفض أي اعتداء أو محاولة اقتراب من السفارات والمقار الدبلوماسية المعتمدة في الجمهورية العربية السورية. وشددت الوزارة في بيان نشرته على معرفاتها الرسمية السبت 4 نيسان، على أن هذه المقار محمية بموجب القانون الدولي والاتفاقيات الدبلوماسية، وتعد رمزاً للعلاقات بين الدول والشعوب. كما أعربت عن رفضها القاطع […]',
  'The Ministry of Foreign Affairs and Expatriates affirmed its firm and firm position in rejecting any attack or attempt to approach embassies and diplomatic headquarters accredited in the Syrian Arab Republic. The Ministry stressed, in a statement published on its official websites on Saturday, April 4, that these headquarters are protected under international law and diplomatic agreements, and are a symbol of relations between countries and peoples. It also expressed its categorical rejection [...]',
  'أكدت وزارة الخارجية والمغتربين موقفها الثابت والراسخ في رفض أي اعتداء أو محاولة اقتراب من السفارات والمقار الدبلوماسية المعتمدة في الجمهورية العربية السورية. وشددت الوزارة في بيان نشرته على معرفاتها الرسمية السبت 4 نيسان، على أن هذه المقار محمية بموجب القانون الدولي والاتفاقيات الدبلوماسية، وتعد رمزاً للعلاقات بين الدول والشعوب. كما أعربت عن رفضها القاطع واستنكارها لأي شعارات أو أفعال مسيئة للدول أو المساس برموزها، مؤكدةً أن هذا التصرف يتناقض مع مبادئ الاحترام المتبادل والتعاون الدولي. وفي إطار احترام حقوق المواطنين في التعبير عن آرائهم، أكدت الوزارة أهمية ممارسة هذا الحق ضمن إطار القوانين والأنظمة المعمول بها، مع الالتزام الكامل بالحفاظ على الأمن العام ، بعيداً عن أي ممارسات قد تخل بالاستقرار أو تمس وتتقرب من السفارات والمقار الدبلوماسية المعتمدة.',
  'The Ministry of Foreign Affairs and Expatriates affirmed its firm and firm position in rejecting any attack or attempt to approach embassies and diplomatic headquarters accredited in the Syrian Arab Republic. The Ministry stressed, in a statement published on its official websites on Saturday, April 4, that these headquarters are protected under international law and diplomatic agreements, and are a symbol of relations between countries and peoples. It also expressed its categorical rejection and denunciation of any slogans or actions that are offensive to countries or harm their symbols, stressing that this behavior contradicts the principles of mutual respect and international cooperation. In the context of respecting the rights of citizens to express their opinions, the Ministry stressed the importance of exercising this right within the framework of applicable laws and regulations, with full commitment to maintaining public security, away from any practices that may disturb stability or affect and approach accredited embassies and diplomatic headquarters.',
  'https://alikhbariah.com/wp-content/uploads/2026/04/Ministry-of-Foreign-Affairs-and-Expatriates.jpg',
  'https://alikhbariah.com/%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9-%d8%aa%d8%a4%d9%83%d8%af-%d8%b1%d9%81%d8%b6%d9%87%d8%a7-%d8%a3%d9%8a-%d8%a7%d8%b9%d8%aa%d8%af%d8%a7%d8%a1-%d8%b9%d9%84%d9%89-%d8%a7%d9%84%d8%b3%d9%81/',
  (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1),
  (select id from public.locations where slug = 'syria' limit 1),
  '2026-04-03T20:08:11Z'::timestamptz,
  false, false, true, 0
where not exists (
  select 1 from public.news n where n.title = 'الخارجية تؤكد رفضها أي اعتداء على السفارات المعتمدة والمساس برموز الدول'
     or coalesce(to_jsonb(n)->>'source_url','') = 'https://alikhbariah.com/%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9-%d8%aa%d8%a4%d9%83%d8%af-%d8%b1%d9%81%d8%b6%d9%87%d8%a7-%d8%a3%d9%8a-%d8%a7%d8%b9%d8%aa%d8%af%d8%a7%d8%a1-%d8%b9%d9%84%d9%89-%d8%a7%d9%84%d8%b3%d9%81/'
);

